Value.Calculation:
Let ( [
  ~raw = If ( IsEmpty ( store_catalogue::language ) ; store_catalogue::name ; store_catalogue::language ) ;
  ~lang = Case (
    PatternCount ( ~raw ; "bil" ) ; "Bilingual" ;
    PatternCount ( ~raw ; "eng" ) and PatternCount ( ~raw ; "fr" ) ; "Bilingual" ;
    PatternCount ( ~raw ; "fr" ) ; "French" ;
    PatternCount ( ~raw ; "eng" ) ; "English" ;
    ""
  )
] ;
  JSONSetElement ( "{}" ;
    [ "id" ; store_catalogue::id ; JSONNumber ] ;
    [ "code" ; store_catalogue::code ; JSONString ] ;
    [ "language" ; ~lang ; JSONString ] ;
    [ "nameKey" ; If ( IsEmpty ( ~lang ) ; "" ; "label_colliers_product" & ~lang ) ; JSONString ] ;
    [ "price" ; If ( IsEmpty ( store_catalogue::sell ) ; 63 ; store_catalogue::sell ) ; JSONNumber ]
  )
)
